import{_ as s,r,o as d,c as l,a as t,b as o,d as i,w as c,e as h}from"./chunks/framework.CJ137FEY.js";const v=JSON.parse('{"title":"What is OreUI?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),g={name:"guide/introduction.md"},p={style:{"margin-top":"24px"}};function u(m,e,b,f,y,_){const a=r("OreBanner"),n=r("OreButton");return d(),l("div",null,[e[1]||(e[1]=t("h1",{id:"what-is-oreui",tabindex:"-1"},[o("What is OreUI? "),t("a",{class:"header-anchor",href:"#what-is-oreui","aria-label":'Permalink to "What is OreUI?"'},"​")],-1)),i(a,{type:"info"},{default:c(()=>[...e[0]||(e[0]=[o(" OreUI is the modern cross-platform UI design system and interaction standard created by Mojang Studios for Minecraft: Bedrock Edition. ",-1)])]),_:1}),e[2]||(e[2]=h('<p><strong>Spectrollay Ore UI</strong> (<a href="https://github.com/Spectrollay-OreUI/OreUI" target="_blank" rel="noreferrer">GitHub Repository</a>) brings this design philosophy to the web, delivering authentic pixel aesthetics, mechanical 3D down-press tactile feedback, immersive sound effects, and full accessibility standards.</p><hr><h2 id="🎨-core-design-principles" tabindex="-1">🎨 Core Design Principles <a class="header-anchor" href="#🎨-core-design-principles" aria-label="Permalink to &quot;🎨 Core Design Principles&quot;">​</a></h2><h3 id="_1-tactile-3d-depth" tabindex="-1">1. Tactile 3D Depth <a class="header-anchor" href="#_1-tactile-3d-depth" aria-label="Permalink to &quot;1. Tactile 3D Depth&quot;">​</a></h3><p>Unlike flat design frameworks, OreUI embraces <strong>Bevel Inset Shadows</strong> and <strong>Specular Highlights</strong>:</p><ul><li>Buttons exhibit a raised, mechanical look in their idle state.</li><li>Upon clicking, the button depresses by <code>4px</code> with synchronized padding adjustments for realistic mechanical response.</li></ul><h3 id="_2-immersive-web-audio-feedback" tabindex="-1">2. Immersive Web Audio Feedback <a class="header-anchor" href="#_2-immersive-web-audio-feedback" aria-label="Permalink to &quot;2. Immersive Web Audio Feedback&quot;">​</a></h3><p>OreUI includes the official Minecraft Bedrock sound library embedded directly in memory:</p><ul><li><strong>General buttons &amp; links</strong>: Crisp <code>click.ogg</code> wood tick.</li><li><strong>Primary green actions</strong>: Solid <code>button.ogg</code> confirmation.</li><li><strong>Drawers &amp; dropdowns</strong>: <code>drawer_open.ogg</code> and <code>drawer_close.ogg</code>.</li><li><strong>Toasts &amp; Level-up</strong>: <code>toast.ogg</code> and <code>xp.ogg</code>.</li></ul><h3 id="_3-tiered-minecraft-typography" tabindex="-1">3. Tiered Minecraft Typography <a class="header-anchor" href="#_3-tiered-minecraft-typography" aria-label="Permalink to &quot;3. Tiered Minecraft Typography&quot;">​</a></h3><ul><li><strong>Minecraft Ten</strong>: Main titles, hero headings, and brand typography.</li><li><strong>Minecraft Seven</strong>: Section headers (H2/H3), card titles, and modal headers.</li><li><strong>Minecraft Five</strong>: Status badges, version indicators, and micro tags.</li><li><strong>Noto Sans</strong>: General readable body paragraphs and documentation text.</li></ul><hr><h2 id="🚀-why-choose-oreui-vitepress-theme" tabindex="-1">🚀 Why Choose OreUI VitePress Theme? <a class="header-anchor" href="#🚀-why-choose-oreui-vitepress-theme" aria-label="Permalink to &quot;🚀 Why Choose OreUI VitePress Theme?&quot;">​</a></h2><ul><li><strong>Zero-Config Setup</strong>: Automatically restyles VitePress navigation, sidebars, code blocks, callouts, and footers.</li><li><strong>Vue 3 Components</strong>: Write <code>&lt;OreButton&gt;</code>, <code>&lt;OreSwitch&gt;</code>, <code>&lt;OreModal&gt;</code>, etc., directly in Markdown.</li><li><strong>Fully Responsive</strong>: Adapts seamlessly to mobile, tablet, and widescreen layouts.</li><li><strong>Built-in Sound Manager</strong>: Memory-cached audio with navbar mute/volume controls.</li></ul>',14)),t("div",p,[i(n,{variant:"green",text:"Next: Getting Started →",href:"/guide/getting-started"})])])}const w=s(g,[["render",u]]);export{v as __pageData,w as default};
